export function tr(key:string,values:Record<string,string|number>={},language:Lang=lang):string {
 const dict=language==='de'?transcriptionDe:transcriptionEn;
 if(key==='counts')return ['warning','uncertainty'].map((kind,i)=>{const n=Number(values[i===0?'warnings':'uncertainties']);return tr(`${kind}Count${n===1?'One':'Other'}`,{n},language);}).join(' · ');
 if(key==='pages'&&Number(values.n)===1)key='pagesOne';
 return Object.entries(values).reduce((s,[k,v])=>s.replaceAll(`{${k}}`,String(v)),dict[key as keyof typeof dict]??dict.unknown);
}

